namespace Quantum.Superposition {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Measurement;

    @EntryPoint()
    operation DemonstrateSuperposition() : Unit {
        use q = Qubit();

        // Create |+⟩ state
        H(q);

        // Demonstrate that |+⟩ is definite in X basis
        // First transform to Z basis (which swaps X and Z)
        H(q);
        let result = M(q);
        Message($"Measuring |+⟩ in X basis via H transform: {result}");

        // Create |0⟩, should be definite
        Reset(q);
        let result2 = M(q);
        Message($"Measuring |0⟩: {result2}");
    }
}
